class Solution {
public:
    int strangePrinter(string s) {
        if (s.empty()) return 0;
        int n = s.size();
        vector<vector<int>> dp(n, vector<int>(n, 0));
        for (int i = 0; i < n; ++i) dp[i][i] = 1;
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                dp[i][j] = dp[i][j - 1] + 1;
                for (int k = i; k < j; ++k) {
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] - (s[k] == s[j] ? 1 : 0));
                }
            }
        }
        return dp[0][n - 1];
    }
};

class Solution {
    public int strangePrinter(String s) {
        if (s.isEmpty()) return 0;
        int n = s.length();
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; ++i) dp[i][i] = 1;
        for (int len = 2; len <= n; ++len) {
            for (int i = 0; i <= n - len; ++i) {
                int j = i + len - 1;
                dp[i][j] = dp[i][j - 1] + 1;
                for (int k = i; k < j; ++k) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] - (s.charAt(k) == s.charAt(j) ? 1 : 0));
                }
            }
        }
        return dp[0][n - 1];
    }
}

var strangePrinter = function(s) {
    if (!s) return 0;
    const n = s.length;
    const dp = Array.from({ length: n }, () => new Int32Array(n));
    for (let i = 0; i < n; ++i) dp[i][i] = 1;
    for (let len = 2; len <= n; ++len) {
        for (let i = 0; i <= n - len; ++i) {
            const j = i + len - 1;
            dp[i][j] = dp[i][j - 1] + 1;
            for (let k = i; k < j; ++k) {
                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] - (s[k] === s[j] ? 1 : 0));
            }
        }
    }
    return dp[0][n - 1];
};
